do $guard$ declare f record; definition text; begin for f in select p.oid::regprocedure as signature,pg_get_functiondef(p.oid) as definition from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in ('admin_disable_2fa','admin_enable_2fa','admin_password_expired','admin_validate_session','admin_record_failed_login','admin_reset_failed_logins','admin_global_search') loop if position('perform public.assert_is_admin();' in f.definition)=0 then execute regexp_replace(f.definition,'\mbegin\M',E'begin\n perform public.assert_is_admin();','i'); end if; execute format('revoke execute on function %s from public,anon',f.signature); end loop; end $guard$; revoke execute on function public.increment_counter(text,text,uuid,text,integer) from public,anon,authenticated; grant execute on function public.increment_counter(text,text,uuid,text,integer) to service_role;
